import{_ as a,o,c as r,a5 as i}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Versão preliminar TikTools 4.2.1-rc.3","description":"","frontmatter":{"title":"Versão preliminar TikTools 4.2.1-rc.3","docId":"releases.4.2.1-rc.3","translationKey":"releases.4.2.1-rc.3","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3fa36e41656e0c6d288286b333984d1334fb5174054cdadb489464890c6196ea","translationRevision":"f0a3bd3623dfdd44d6251ebc68b960a9b16f3953362c6511503c1022d3dad35b","order":30},"headers":[],"relativePath":"pt/releases/4.2.1-rc.3.md","filePath":"pt/releases/4.2.1-rc.3.md","lastUpdated":1794611623000}'),s={name:"pt/releases/4.2.1-rc.3.md"};function t(d,e,c,n,l,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc3" tabindex="-1">TikTools 4.2.1-rc.3 <a class="header-anchor" href="#tiktools-421-rc3" aria-label="Permalink to &quot;TikTools 4.2.1-rc.3 {#tiktools-421-rc3}&quot;">​</a></h1><h2 id="goal-release-status-and-prerequisites" tabindex="-1">Objetivo, status da versão e pré-requisitos <a class="header-anchor" href="#goal-release-status-and-prerequisites" aria-label="Permalink to &quot;Objetivo, status da versão e pré-requisitos {#goal-release-status-and-prerequisites}&quot;">​</a></h2><p>RC3 é uma versão preliminar publicada, conforme informado em 13 de novembro de 2026. Use-a para avaliar as alterações de desktop Linux após a RC2, com backup e perfil de teste separado. É uma candidata, não uma atualização do canal estável. Baixe o artefato publicado AppImage, DEB ou portátil e seu <code>SHA256SUMS.txt</code> da <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versões</a>; os pacotes registrados foram compilados localmente.</p><p>Recuperação de seções do Cloud e colaboração continuam experimentais. A instalação não implanta migrações do backend nem comprova compatibilidade de contas em produção.</p><h2 id="changes-available-in-rc3" tabindex="-1">Alterações disponíveis na RC3 <a class="header-anchor" href="#changes-available-in-rc3" aria-label="Permalink to &quot;Alterações disponíveis na RC3 {#changes-available-in-rc3}&quot;">​</a></h2><ul><li>Mantém a correção da RC2 para leituras concorrentes de comparação e nova tentativa local com o motivo nativo da falha.</li><li>Variables persiste tipos texto, número, booleano, lista e segredo local. Salvamentos atômicos rejeitam um host alterado ou revisão desatualizada do editor, preservando a renderização de texto de modelos existente.</li><li>Segredos permanecem mascarados. Trocar de host não pode recorrer a uma gravação legada, e a classificação nativa exclui valores enfileirados antes de se tornarem secretos de publicações e saídas de comparação posteriores.</li><li>A ponte nativa de Variables permite comparação em cache, adoção explícita de uma variável e download somente para cache. A aplicação verifica novamente sessão, consentimento, revisão local e entrada de cache.</li></ul><p>Salvar Variables permanece local. A RC3 não expõe o botão completo Changes de Variables com envio/retirada revisados e tratamento de conflitos pendentes; essa integração de seção é descrita nas <a href="./4.2.2.html">notas de código da 4.2.2</a>. Marcar um valor local como secreto não apaga uma cópia publicada anteriormente no Cloud.</p><h2 id="check-the-published-candidate" tabindex="-1">Verifique a candidata publicada <a class="header-anchor" href="#check-the-published-candidate" aria-label="Permalink to &quot;Verifique a candidata publicada {#check-the-published-candidate}&quot;">​</a></h2><ol><li>Verifique a soma de verificação do pacote e a versão exibida <code>4.2.1-rc.3</code>. Mantenha o perfil de teste e os diretórios XDG separados do perfil normal.</li><li>Crie uma variável de texto inofensiva como <code>demoGreeting = &quot;Olá&quot;</code>, salve e recarregue. Verifique os outros tipos explícitos com valores de amostra não sensíveis.</li><li>Abra Changes e exercite carregamento/nova tentativa local. Inspecione Settings/Teams e ajuda guiada opcional sem tratar capacidades ausentes do backend como configuração bem-sucedida.</li><li>Informe ação exata, versão, motivo nativo e ID da requisição para qualquer falha. Mantenha tokens, códigos de convite e valores secretos fora dos relatórios.</li></ol><h2 id="expected-result-evidence-and-recovery" tabindex="-1">Resultado esperado, evidências e recuperação <a class="header-anchor" href="#expected-result-evidence-and-recovery" aria-label="Permalink to &quot;Resultado esperado, evidências e recuperação {#expected-result-evidence-and-recovery}&quot;">​</a></h2><p>Valores locais tipados devem sobreviver ao recarregamento, enquanto edições com host ou revisão desatualizados falham visivelmente. O registro original informa verificações nativas de Variables/sincronização/paridade, testes de navegador com host simulado, verificação CLI em sandbox, verificações de conteúdo do instalador e inicialização frontend-ready com perfil isolado vazio. Ele não demonstra sincronização autenticada em produção nem reprodução de mídia.</p><p>O SHA-256 registrado do AppImage é <code>4b11260836457350debf2680b230c52cea8408ddf17ccdc729d0025a62149b7e</code>; verifique o arquivo de somas de verificação que acompanha o download. Em falha, preserve o perfil copiado e use a <a href="./../user/preferences/troubleshooting.html">solução de problemas</a> antes de repetir ações de recuperação.</p><p>Convites por apelido dependem do backend <code>6a69c99</code> e da migração <code>20261113000001_remote_invitation_recipients.sql</code>. O registro antigo observou uma rota de pessoas ausente; nenhuma nova sondagem de produção é afirmada aqui. Transporte Cloud de Automations, revisões de Overlays e a auditoria restante de colaboração estavam inacabados, e o detentor histórico do bloqueio SQLite permanecia desconhecido.</p><p>O <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.3.md" target="_blank" rel="noreferrer">registro original da versão</a> é mantido como evidência datada. Volte ao <a href="./">índice de versões</a>.</p>',14)])])}const v=a(s,[["render",t]]);export{u as __pageData,v as default};
